/**
 * JavaScript code to detect available availability of a
 * particular font in a browser using JavaScript and CSS.
 *
 * Author : Lalit Patel
 * Website: http://www.lalit.org/lab/javascript-css-font-detect/
 * License: Apache Software License 2.0
 *          http://www.apache.org/licenses/LICENSE-2.0
 * Version: 0.15 (21 Sep 2009)
 *          Changed comparision font to default from sans-default-default,
 *          as in FF3.0 font of child element didn't fallback
 *          to parent element if the font is missing.
 * Version: 0.2 (04 Mar 2012)
 *          Comparing font against all the 3 generic font families ie,
 *          'monospace', 'sans-serif' and 'sans'. If it doesn't match all 3
 *          then that font is 100% not available in the system
 * Version: 0.3 (24 Mar 2012)
 *          Replaced sans with serif in the list of baseFonts
 */

/**
 * Usage: d = new Detector();
 *        d.detect('font name');
 */
function createProbe() {
    // Keep the exact upstream glyphs and size for both measurement and warming.
    var span = document.createElement('span');
    //we test using 72px font size, we may use any size. I guess larger the better.
    span.style.fontSize = '72px';
    //we use m or w because these two characters take up the maximum width.
    // And we use a LLi so that the same matching fonts can get separated
    span.innerHTML = 'mmmmmmmmmmlli';
    return span;
}

module.exports = function Detector() {
    // a font will be compared against all the three default fonts.
    // and if it doesn't match all 3 then that font is not available.
    var baseFonts = ['monospace', 'sans-serif', 'serif'];

    var h = document.getElementsByTagName("body")[0];

    // create a SPAN in the document to get the width of the text we use to test
    var s = createProbe();
    var defaultWidth = {};
    var defaultHeight = {};
    for (var index in baseFonts) {
        //get the default width for the three base fonts
        s.style.fontFamily = baseFonts[index];
        h.appendChild(s);
        defaultWidth[baseFonts[index]] = s.offsetWidth; //width for the default font
        defaultHeight[baseFonts[index]] = s.offsetHeight; //height for the defualt font
        h.removeChild(s);
    }

    function detect(font) {
        var detected = false;
        for (var index in baseFonts) {
            s.style.fontFamily = font + ',' + baseFonts[index]; // name of the font along with the base font for fallback.
            h.appendChild(s);
            var matched = (s.offsetWidth != defaultWidth[baseFonts[index]] || s.offsetHeight != defaultHeight[baseFonts[index]]);
            h.removeChild(s);
            detected = detected || matched;
        }
        return detected;
    }

    this.detect = detect;

    // AgarCity: batch only the font-list probe. Keep the constructor's original
    // generic metrics and public single-font detector unchanged.
    this.detectMany = function(fonts) {
        var nodes = [];
        var fragment = document.createDocumentFragment();
        for (var i = 0; i < fonts.length; i++) {
            for (var j = 0; j < baseFonts.length; j++) {
                var node = s.cloneNode(true);
                node.style.fontFamily = fonts[i] + ',' + baseFonts[j];
                nodes.push(node);
                fragment.appendChild(node);
            }
        }
        h.appendChild(fragment);
        var results = [];
        try {
            for (var i = 0; i < fonts.length; i++) {
                var detected = false;
                for (var j = 0; j < baseFonts.length; j++) {
                    var node = nodes[i * baseFonts.length + j];
                    var matched = node.offsetWidth != defaultWidth[baseFonts[j]] || node.offsetHeight != defaultHeight[baseFonts[j]];
                    detected = detected || matched;
                }
                results.push(detected);
            }
        } finally {
            for (var i = 0; i < nodes.length; i++) h.removeChild(nodes[i]);
        }
        return results;
    };
};

// Opt-in cache warming, never a font-result cache. Each task leaves no nodes.
// Skip declared web fonts so preparation cannot start their downloads earlier.
module.exports.prepareFonts = function(fonts, batchSize) {
    var next = 0;
    var template = createProbe();
    var timer = setTimeout(step, 0);

    function step() {
        timer = null;
        var declared = new Set();
        document.fonts.forEach(function(face) {
            declared.add(face.family.replace(/^['"]|['"]$/g, '').toLowerCase());
        });
        var fragment = document.createDocumentFragment();
        var nodes = [];
        var end = Math.min(next + batchSize, fonts.length);
        while (next < end) {
            var font = fonts[next++];
            if (declared.has(font.toLowerCase())) continue;
            var node = template.cloneNode(true);
            node.style.fontFamily = font + ',monospace';
            nodes.push(node);
            fragment.appendChild(node);
        }
        if (nodes.length) {
            document.body.appendChild(fragment);
            try {
                // One read resolves the whole batch; discard its metrics.
                void nodes[nodes.length - 1].offsetWidth;
            } finally {
                for (var i = 0; i < nodes.length; i++) document.body.removeChild(nodes[i]);
            }
        }
        if (next < fonts.length) timer = setTimeout(step, 0);
        else template = null;
    }

    return function cancel() {
        if (timer !== null) clearTimeout(timer);
        timer = null;
        template = null;
    };
};
